         box-shadow: none;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>

   <header class="site-header">
     <a class="brand" href="#" aria-label="Acme Support home">
       <span class="brand-mark" aria-hidden="true">A</span>
       <span>Acme Support</span>
     </a>
   </header>

   <main id="main-content">
     <section class="support-card" aria-labelledby="page-title">
       <div>
         <p class="eyebrow">Support request</p>
         <h1 id="page-title">How can we help?</h1>
         <p class="intro">
           Send our support team your contact details and we will connect you with the right specialist.
         </p>
         <ul class="details" aria-label="Support expectations">
           <li>
             <span class="check" aria-hidden="true">✓</span>
             <span>Required fields are marked with an asterisk.</span>
           </li>
           <li>
             <span class="check" aria-hidden="true">✓</span>
             <span>We use your phone number only if calling is the fastest way to help.</span>
           </li>
         </ul>
       </div>

       <div class="form-panel">
         <h2 class="form-heading">Contact details</h2>
         <p class="form-note">Share the best way for our team to reach you.</p>

         <form class="contact-form" id="support-form" novalidate>
           <div class="form-field">
             <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
             <input
               id="full-name"
               name="full-name"
               type="text"
               autocomplete="name"
               required
               aria-required="true">
           </div>

           <div class="form-field">
             <label for="email">Email address <span class="required" aria-hidden="true">*</span></label>
             <input
               id="email"
               name="email"
               type="email"
               autocomplete="email"
               inputmode="email"
               required
               aria-required="true">
           </div>

           <div class="form-field">
             <label for="phone">Phone number <span class="optional">(optional)</span></label>
             <input
               id="phone"
               name="phone"
               type="tel"
               autocomplete="tel"
               inputmode="tel"
               aria-describedby="phone-helper">
             <p class="helper-text" id="phone-helper">Use a country code and area code when possible, for example +1 555 123 4567.</p>
           </div>

           <div class="form-actions">
             <button type="submit">Submit support request</button>
             <p class="status" id="form-status" aria-live="polite"></p>
           </div>
         </form>
       </div>
     </section>
   </main>

   <footer class="site-footer">
     <p>&copy; 2026 Acme Support. We usually respond within one business day.</p>
   </footer>

   <script>
     const form = document.querySelector("#support-form");
     const statusMessage = document.querySelector("#form-status");
     const fields = Array.from(form.querySelectorAll("input"));

     const updateInvalidState = (field) => {
       if (field.validity.valid) {
         field.removeAttribute("aria-invalid");
         return;
       }

       field.setAttribute("aria-invalid", "true");
     };

     form.addEventListener("submit", (event) => {
       event.preventDefault();
       statusMessage.textContent = "";

       fields.forEach(updateInvalidState);

       const firstInvalidField = fields.find((field) => !field.validity.valid);

       if (firstInvalidField) {
         firstInvalidField.focus();
         firstInvalidField.reportValidity();
         return;
       }

       form.reset();
       fields.forEach((field) => field.removeAttribute("aria-invalid"));
       statusMessage.textContent = "Thanks. Your support request has been prepared.";
     });

     fields.forEach((field) => {
       field.addEventListener("input", () => {
         if (field.hasAttribute("aria-invalid")) {
           updateInvalidState(field);
         }

         statusMessage.textContent = "";
       });
     });
   </script>
')
